// Minimal stand-in for the Data Injection interface implemented by the generated `...Injection` classes,
// loaded only when the plugin is absent so their rights can be tested.
// It mirrors Data Injection 2.15: keep it in sync if the interface changes there.
interface PluginDatainjectionInjectionInterface
{
    public function isPrimaryType();

    public function connectedTo();

    public function getOptions($primary_type = '');

    public function addOrUpdateObject($values = [], $options = []);
}
